// Returns the sum of the squares of every number in arr.
// Each element is squared, then the squares are added together.
// Example: sumSquares([1, 2, 3]) returns 14.
function sumSquares(arr) {
  let total = 0;                 // running total of squared values
  for (const n of arr) {         // visit each element once
    total += n * n;              // add the square of the current element
  }
  return total;                  // hand back the final sum
}
EOF

